// FAQ answer for the faq route. Threshold from calibration (exec #547, 2026-10-19):
// real FAQ paraphrases scored 0.678-0.929. Outside the faq route the scores of NON-FAQ questions
// reached 0.905, so this lookup is only safe AFTER the router has picked "faq".
const THRESHOLD = 0.65;
const base = $('Input').first().json;
let best = null;
const top = [];
for (const it of $input.all()) {
  const d = it.json;
  if (!d?.document || typeof d.score !== 'number') continue;
  top.push({ faq_id: d.document.metadata?.faq_id ?? null, score: Math.round(d.score * 1000) / 1000 });
  if (!best || d.score > best.score) best = d;
}
const hit = !!best && best.score >= THRESHOLD && !!best.document.metadata?.answer;
return [{ json: {
  ...base,
  faq_hit: hit,
  output: hit ? String(best.document.metadata.answer) : undefined,
  route: 'faq',
  tool_calls: [{ tool: 'faq_match', input: { query: base.user_text, threshold: THRESHOLD }, output: { hit, top } }],
} }];

// CONTRACT (every branch ends with a Return node that outputs exactly this shape):
// { update_id, chat_id, route, output, tool_calls[], router{decided_by,pass,model,error}, faq{hit,top_score}|null }
// A branch that FAILS also returns the contract (route 'router_error' + apology), so the caller always gets ONE result.
const ctx = $('Input').first().json;   // what the main workflow passed in (Route Decided)
const contract = (route, output, tool_calls, faq = null) => [{ json: {
  update_id: ctx.update_id, chat_id: ctx.chat_id, route,
  output: String(output ?? '').trim(), tool_calls: Array.isArray(tool_calls) ? tool_calls : [],
  router: ctx.router, faq } }];
const failed = (branch, err) => {
  const ar = /[\u0600-\u06FF]/.test(String(ctx.user_text || ''));
  const msg = typeof err === 'string' ? err : JSON.stringify(err ?? 'unknown_error').slice(0, 300);
  return contract('router_error',
    ar ? 'معلش، عندي مشكلة مؤقتة دلوقتي 🙏 ممكن حضرتك تبعت رسالتك تاني بعد شوية؟'
       : "Sorry, I'm having a temporary problem right now 🙏 Could you send your message again in a little while?",
    [{ tool: 'error', input: { failed_in: branch }, output: { error: msg } }]);
};

// In: FAQ Hit? (stored answer) OR FAQ Miss Answer (Gemini, field `text`) OR its error output.
const fq = $('Pick FAQ').first().json;
const top = fq.tool_calls?.[0]?.output?.top?.[0]?.score ?? null;
if (fq.faq_hit) return contract('faq', fq.output, fq.tool_calls, { hit: true, top_score: top });
if ($json.error || !String($json.text ?? '').trim()) return failed('faq_fallback', $json.error?.message ?? $json.error ?? 'empty_answer');
return contract('faq_fallback', $json.text, fq.tool_calls, { hit: false, top_score: top });
